 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelHeaviside {
public:
    __aicore__ inline KernelHeaviside() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR values, GM_ADDR output,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, formerLength);
            valuesGm.SetGlobalBuffer((__gm__ T *)values + offset, formerLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
            valuesGm.SetGlobalBuffer((__gm__ T *)values + offset, tailLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueInput, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueValues, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueOutput, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: need temp buffers for computation
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
        } else {
            // FP16/BF16: need FP32 cast buffers
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf5, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> inputLocal = inQueueInput.AllocTensor<T>();
        AscendC::LocalTensor<T> valuesLocal = inQueueValues.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(inputLocal, inputGm[progress * this->tileLength], copyParams);
        AscendC::DataCopyPad(valuesLocal, valuesGm[progress * this->tileLength], copyParams);

        inQueueInput.EnQue(inputLocal);
        inQueueValues.EnQue(valuesLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> inputLocal = inQueueInput.DeQue<T>();
        AscendC::LocalTensor<T> valuesLocal = inQueueValues.DeQue<T>();
        AscendC::LocalTensor<T> outputLocal = outQueueOutput.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 path: direct computation
            ComputeHeavisideFp32(inputLocal, valuesLocal, outputLocal, curTileLength);
        } else {
            // FP16/BF16 path: cast to FP32 -> compute -> cast back
            AscendC::LocalTensor<float> inputFp32 = tmpBuf1.Get<float>();
            AscendC::LocalTensor<float> valuesFp32 = tmpBuf2.Get<float>();
            AscendC::LocalTensor<float> outputFp32 = tmpBuf3.Get<float>();

            AscendC::Cast(inputFp32, inputLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(valuesFp32, valuesLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            ComputeHeavisideFp32(inputFp32, valuesFp32, outputFp32, curTileLength);

            AscendC::Cast(outputLocal, outputFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        outQueueOutput.EnQue<T>(outputLocal);
        inQueueInput.FreeTensor(inputLocal);
        inQueueValues.FreeTensor(valuesLocal);
    }

    __aicore__ inline void ComputeHeavisideFp32(AscendC::LocalTensor<float> input,
                                                 AscendC::LocalTensor<float> values,
                                                 AscendC::LocalTensor<float> output,
                                                 int64_t len)
    {
        // Heaviside: H(x, v) = 0 if x < 0, v if x == 0, 1 if x > 0
        // Implementation using vector operations:
        // Step 1: pos_part = Max(input, 0)  -- positive values (or 0)
        // Step 2: neg_part = Min(input, 0)  -- negative values (or 0)
        // Step 3: abs_input = Abs(input)    -- absolute values
        // Step 4: is_pos = (pos_part > 0) indicator
        //         Use: is_pos = pos_part / (abs_input + epsilon)
        //         When x > 0: pos_part = x, abs = x, is_pos = x/(x+eps) ≈ 1
        //         When x = 0: pos_part = 0, abs = 0, is_pos = 0/(0+eps) = 0
        //         When x < 0: pos_part = 0, abs = |x|, is_pos = 0/(|x|+eps) = 0
        // Step 5: is_neg = (neg_part < 0) indicator
        //         Use: is_neg = Abs(neg_part) / (abs_input + epsilon)
        //         When x < 0: neg_part = x, abs(neg) = |x|, abs = |x|, is_neg = |x|/(|x|+eps) ≈ 1
        //         When x = 0: neg_part = 0, abs(neg) = 0, abs = 0, is_neg = 0/(0+eps) = 0
        //         When x > 0: neg_part = 0, abs(neg) = 0, abs = x, is_neg = 0/(x+eps) = 0
        // Step 6: is_zero = 1 - is_pos - is_neg
        // Step 7: output = is_pos * 1.0 + is_zero * values

        AscendC::LocalTensor<float> posPart = tmpBuf1.Get<float>();
        AscendC::LocalTensor<float> negPart = tmpBuf2.Get<float>();
        AscendC::LocalTensor<float> absInput = tmpBuf3.Get<float>();

        // pos_part = Max(input, 0)
        AscendC::Maxs(posPart, input, 0.0f, len);
        // neg_part = Min(input, 0)
        AscendC::Mins(negPart, input, 0.0f, len);
        // abs_input = Abs(input)
        AscendC::Abs(absInput, input, len);

        // Use epsilon to avoid division by zero
        // eps_buf = abs_input + epsilon
        AscendC::Adds(absInput, absInput, 1e-7f, len);

        // is_pos = pos_part / (abs_input + epsilon)
        AscendC::Div(posPart, posPart, absInput, len);

        // is_neg = Abs(neg_part) / (abs_input + epsilon)
        // Recompute abs_input since we modified it
        AscendC::LocalTensor<float> absNeg = tmpBuf2.Get<float>();
        AscendC::Abs(absNeg, negPart, len);
        AscendC::Div(negPart, absNeg, absInput, len);

        // is_zero = 1.0 - is_pos - is_neg
        AscendC::LocalTensor<float> oneBuf = tmpBuf2.Get<float>();
        AscendC::Duplicate(oneBuf, 1.0f, len);
        AscendC::Sub(oneBuf, oneBuf, posPart, len);
        AscendC::Sub(oneBuf, oneBuf, negPart, len);

        // output = is_pos * 1.0 + is_zero * values
        // = posPart * 1.0 + oneBuf * values
        AscendC::LocalTensor<float> result = tmpBuf3.Get<float>();
        AscendC::Mul(result, oneBuf, values, len);
        AscendC::Add(output, result, posPart, len);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> outputLocal = outQueueOutput.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outputGm[progress * this->tileLength], outputLocal, copyParams);
        outQueueOutput.FreeTensor(outputLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueInput;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueValues;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueOutput;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf5;
    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> valuesGm;
    AscendC::GlobalTensor<T> outputGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void heaviside(GM_ADDR input, GM_ADDR values, GM_ADDR output,
                                                  int64_t formerNum, int64_t formerLength,
                                                  int64_t tailLength, int64_t tileLength,
                                                  int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelHeaviside<half> op;
        op.Init(input, values, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelHeaviside<float> op;
        op.Init(input, values, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
