        AscendC::Duplicate(isZero, 1.0f, len);
        AscendC::Sub(isZero, isZero, posPart, len);
        AscendC::Sub(isZero, isZero, negPart, len);

        // Step 9: output = isZero * values + isPos * 1.0
        //         = isZero * values + isPos
        AscendC::Mul(result, isZero, values, len);
        AscendC::Add(output, result, posPart, len);
    }

