        AscendC::LocalTensor<float> negPart = bufNeg.Get<float>();
        AscendC::LocalTensor<float> absInput = bufAbs.Get<float>();
        AscendC::LocalTensor<float> isZero = bufZero.Get<float>();
        AscendC::LocalTensor<float> result = bufRes.Get<float>();

        AscendC::Maxs(posPart, input, 0.0f, len);
        AscendC::Mins(negPart, input, 0.0f, len);
        AscendC::Abs(absInput, input, len);

        AscendC::Adds(absInput, absInput, 1e-7f, len);

        AscendC::Div(posPart, posPart, absInput, len);

        AscendC::Abs(negPart, negPart, len);
        AscendC::Div(negPart, negPart, absInput, len);

        AscendC::Duplicate(isZero, 1.0f, len);
        AscendC::Sub(isZero, isZero, posPart, len);
        AscendC::Sub(isZero, isZero, negPart, len);

        AscendC::Mul(result, isZero, values, len);
        AscendC::Add(output, result, posPart, len);
