    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueValues;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueOutput;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufA;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufB;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufC;
    AscendC::TBuf<AscendC::TPosition::VECCALC> bufD;
