#include "torch_kernel_helper.h"

#include "aclrtlaunch_heaviside.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor heaviside(const at::Tensor &input, const at::Tensor &values)
{
    /* create a result tensor */
    at::Tensor output = at::empty_like(input);

    int64_t totalLength = input.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = input.element_size();
    // Use dtypeSize=5 for BF16 to distinguish from FP16 (dtypeSize=2)
    if (input.scalar_type() == at::kBFloat16) {
        dtypeSize = 5;
    }

    /* define the block dim */
    uint32_t blockDim = 8;

    /* tiling params */
    int64_t coreNum = static_cast<int64_t>(blockDim);
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    /* Use conservative tileLength to avoid UB overflow */
    int64_t tileLength = 2048;

    /* launch the kernel function via torch */
    EXEC_KERNEL_CMD(heaviside, blockDim,
                    input, values, output,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize);

    return output;
}

}  // namespace ascend_kernel
