15	template <typename T>
16	class KernelHeaviside {
17	public:
18	    __aicore__ inline KernelHeaviside() {}
19	
20	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR values, GM_ADDR output,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, formerLength);
30	            valuesGm.SetGlobalBuffer((__gm__ T *)values + offset, formerLength);
31	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            inputGm.SetGlobalBuffer((__gm__ T *)input + offset, tailLength);
37	            valuesGm.SetGlobalBuffer((__gm__ T *)values + offset, tailLength);
38	            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
39	        }
40	
41	        this->tileLength = tileLength;
42	
43	        pipe.InitBuffer(inQueueInput, BUFFER_NUM, tileLength * sizeof(T));
44	        pipe.InitBuffer(inQueueValues, BUFFER_NUM, tileLength * sizeof(T));
45	        pipe.InitBuffer(outQueueOutput, BUFFER_NUM, tileLength * sizeof(T));
46	
47	        if constexpr (sizeof(T) != sizeof(float)) {
48	            pipe.InitBuffer(fp32Buf1, tileLength * sizeof(float));
49	            pipe.InitBuffer(fp32Buf2, tileLength * sizeof(float));
50	            pipe.InitBuffer(fp32Buf3, tileLength * sizeof(float));
51	        }
52	
53	        pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
54	    }
55	
56	    __aicore__ inline void Process()
57	    {
58	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
59	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
60	
61	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
62	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
63	
64	        for (int64_t i = 0; i < tileNum - 1; ++i) {
65	            CopyIn(i, this->tileLength);
66	            Compute(i, this->tileLength);
67	            CopyOut(i, this->tileLength);
68	        }
69	        if (tileNum > 0) {
70	            CopyIn(tileNum - 1, alignedTailLen);
71	            Compute(tileNum - 1, alignedTailLen);
72	            CopyOut(tileNum - 1, alignedTailLen);
73	        }
74	    }
