76	private:
77	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
78	    {
79	        AscendC::LocalTensor<T> inputLocal = inQueueInput.AllocTensor<T>();
80	        AscendC::LocalTensor<T> valuesLocal = inQueueValues.AllocTensor<T>();
81	
82	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
83	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
84	        AscendC::DataCopyPad(inputLocal, inputGm[progress * this->tileLength], copyParams, padParams);
85	        AscendC::DataCopyPad(valuesLocal, valuesGm[progress * this->tileLength], copyParams, padParams);
86	
87	        inQueueInput.EnQue(inputLocal);
88	        inQueueValues.EnQue(valuesLocal);
89	    }
