91	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
92	    {
93	        AscendC::LocalTensor<T> inputLocal = inQueueInput.DeQue<T>();
94	        AscendC::LocalTensor<T> valuesLocal = inQueueValues.DeQue<T>();
95	        AscendC::LocalTensor<T> outputLocal = outQueueOutput.AllocTensor<T>();
96	
97	        if constexpr (sizeof(T) == sizeof(float)) {
98	            ComputeHeavisideFp32(inputLocal, valuesLocal, outputLocal, curTileLength);
99	        } else {
100	            AscendC::LocalTensor<float> inputFp32 = fp32Buf1.Get<float>();
101	            AscendC::LocalTensor<float> valuesFp32 = fp32Buf2.Get<float>();
102	            AscendC::LocalTensor<float> outputFp32 = fp32Buf3.Get<float>();
