104	            AscendC::Cast(inputFp32, inputLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
105	            AscendC::Cast(valuesFp32, valuesLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
106	
107	            ComputeHeavisideFp32(inputFp32, valuesFp32, outputFp32, curTileLength);
108	
109	            AscendC::Cast(outputLocal, outputFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
110	        }
111	
112	        outQueueOutput.EnQue<T>(outputLocal);
113	        inQueueInput.FreeTensor(inputLocal);
114	        inQueueValues.FreeTensor(valuesLocal);
115	    }
116	
117	    __aicore__ inline void ComputeHeavisideFp32(AscendC::LocalTensor<float> input,
118	                                                 AscendC::LocalTensor<float> values,
119	                                                 AscendC::LocalTensor<float> output,
120	                                                 int64_t len)
121	    {
122	        AscendC::LocalTensor<float> absXeps = tmpBuf.Get<float>();
123	
124	        AscendC::Maxs(output, input, 0.0f, len);
125	        AscendC::Mins(input, input, 0.0f, len);
126	
127	        AscendC::Sub(absXeps, output, input, len);
128	        AscendC::Adds(absXeps, absXeps, 1e-7f, len);
129	
130	        AscendC::Div(output, output, absXeps, len);
131	
132	        AscendC::Muls(input, input, -1.0f, len);
133	        AscendC::Div(input, input, absXeps, len);
134	
135	        AscendC::Duplicate(absXeps, 1.0f, len);
136	        AscendC::Sub(absXeps, absXeps, output, len);
137	        AscendC::Sub(absXeps, absXeps, input, len);
138	
139	        AscendC::Mul(absXeps, absXeps, values, len);
140	        AscendC::Add(output, absXeps, output, len);
141	    }
