143	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
144	    {
145	        AscendC::LocalTensor<T> outputLocal = outQueueOutput.DeQue<T>();
146	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
147	        AscendC::DataCopyPad(outputGm[progress * this->tileLength], outputLocal, copyParams);
148	        outQueueOutput.FreeTensor(outputLocal);
149	    }
