159	    AscendC::TBuf<AscendC::TPosition::VECCALC> fp32Buf3;
160	    AscendC::GlobalTensor<T> inputGm;
161	    AscendC::GlobalTensor<T> valuesGm;
162	    AscendC::GlobalTensor<T> outputGm;
163	    int64_t blockLength;
164	    int64_t tileLength;
165	};
