167	extern "C" __global__ __aicore__ void heaviside(GM_ADDR input, GM_ADDR values, GM_ADDR output,
168	                                                  int64_t formerNum, int64_t formerLength,
169	                                                  int64_t tailLength, int64_t tileLength,
170	                                                  int64_t dtypeSize)
171	{
172	    if (dtypeSize == 2) {
173	        KernelHeaviside<half> op;
174	        op.Init(input, values, output, formerNum, formerLength, tailLength, tileLength);
175	        op.Process();
176	    } else if (dtypeSize == 4) {
177	        KernelHeaviside<float> op;
178	        op.Init(input, values, output, formerNum, formerLength, tailLength, tileLength);
179	        op.Process();
180	    } else if (dtypeSize == 5) {
181	        // BF16 uses dtypeSize=5 to distinguish from FP16 (dtypeSize=2)
182	        KernelHeaviside<bfloat16_t> op;
183	        op.Init(input, values, output, formerNum, formerLength, tailLength, tileLength);
184	        op.Process();
185	    }
