        // Using Max/Min + Abs with Max(Abs(x), eps) denominator:
        // isPos = Max(x, 0) / Max(Abs(x), eps)
        //   x > 0: x / x = 1 (exact)
        //   x = 0: 0 / eps = 0
        //   x < 0: 0 / |x| = 0
        // isNeg = Abs(Min(x, 0)) / Max(Abs(x), eps)
        //   x < 0: |x| / |x| = 1 (exact)
        //   x = 0: 0 / eps = 0
        //   x > 0: 0 / x = 0
        // isZero = 1 - isPos - isNeg
        // output = isZero * values + isPos * 1.0

        AscendC::LocalTensor<float> absX = tmpBuf.Get<float>();

        // output = Max(input, 0) = posPart
        AscendC::Maxs(output, input, 0.0f, len);

        // input = Min(input, 0) = negPart
        AscendC::Mins(input, input, 0.0f, len);

        // absX = Abs(input_original) = posPart - negPart = output - input
        AscendC::Sub(absX, output, input, len);

